	sections = {
		{
			title = "Resumen",
			text = [=[La Arboleda Vil se encuentra dentro de {link:city-of-dalaran-dungeon}los salones turbados de Dalaran{/link}. Su nombre dice lo que los magos menos desean oír: que la magia vil, el poder de la {link:burning-legion}Legión Ardiente{/link}, ha encontrado un hogar en la ciudad del {link:kirin-tor}Kirin Tor{/link}, y que ha tocado las cosas que crecen. Ningún registro explica todavía cómo llegó a crecer una arboleda en el corazón de {link:city-of-dalaran}Dalaran{/link}, ni cómo llegó a corromperse. Quizá sea uno de los lugares donde la energía demoníaca que perturba la ciudad es más fuerte.]=],
		},
	},
})

