	hint = [=[Enfréntese al fantasma de un archimago que aún recorre los salones de Dalaran.]=],
	allegiance = "Ninguna",
	sections = {
		{
			title = "Resumen",
			text = [=[La Sombra del Archimago es el fantasma de uno de los propios {link:the-wizards-of-ambermill}magos de Dalaran{/link}. Muchos miembros del {link:kirin-tor}Kirin Tor{/link} murieron cuando la {link:scourge}Plaga{/link} y {link:archimonde}Archimonde{/link} cayeron sobre la ciudad en la {link:third-war}Tercera Guerra{/link}. Este no ha encontrado descanso. Recorre los salones de la ciudad a la que sirvió, y no da la bienvenida a los vivos.]=],
		},
		{
			title = "Importancia",
