			text = [=[Ningún registro nombra aún al archimago que fue la Sombra, ni dice por qué el espíritu no puede descansar. El {link:kirin-tor}Kirin Tor{/link}, si lo sabe, no lo ha dicho.]=],
		},
	},
})

Translate("esMX", "lyn-the-ignored", {
